import {windReferenceHeight,windExponent,polarWindSpeed} from './wind-profile.js';
import {sailFlowAtHeight} from './sail-flow.js';
import {getLanguage} from './i18n.js';
export function createWindProfileView(root,button,getState,getMetrics){root.setAttribute('data-i18n-skip','');const lang=(it,en)=>getLanguage()==='en'?en:it,f=(x,n=1)=>Number(x).toLocaleString(getLanguage()==='en'?'en-GB':'it-IT',{minimumFractionDigits:n,maximumFractionDigits:n});let key;
 function update(){const s=getState(),m=getMetrics(),visible=!!s.windProfileVisible;button.setAttribute('aria-expanded',String(visible));button.setAttribute('aria-pressed',String(visible));button.querySelector('small').textContent=visible?lang('Nascondi','Hide'):lang('Mostra','Show');root.classList.toggle('hidden',!visible);if(!visible)return;const next=JSON.stringify([s.windSpeed,s.windAngle,Math.round(m.speed*100),s.boat?.id,s.windShear,getLanguage()]);if(next===key)return;key=next;const wasOpen=root.querySelector('details')?.hasAttribute('open'),H=windReferenceHeight(s),heights=[H,H*.7,H*.4,1.5],rows=heights.map(z=>sailFlowAtHeight(s,z,m.speed)),max=Math.max(1,s.windSpeed),map=z=>150-126*z/H,point=z=>[42+205*sailFlowAtHeight(s,z,m.speed).tws/max,map(z)],curve=Array.from({length:25},(_,i)=>point(1.5+(H-1.5)*i/24));
 root.innerHTML=`<div class="wind-profile-heading"><b>${lang('Vento lungo l’armo','Wind along the rig')}</b><span>${f(s.windSpeed)} kn · ${f(H)} m</span></div><svg class="wind-profile-chart" viewBox="0 0 320 174" role="img" aria-label="${lang('Intensità del vento crescente verso la testa dell’armo','Wind speed increasing towards the rig head')}"><path d="M42 22V152H280" fill="none" stroke="#d4e5f1"/><path d="${curve.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ')}" fill="none" stroke="#2c88c6" stroke-width="2.5"/>${rows.map(r=>{const [x,y]=point(r.height);return`<path d="M42 ${y}H${x}" stroke="#bad9ee" stroke-dasharray="3 4"/><circle cx="${x}" cy="${y}" r="3" fill="#2c88c6"/><text x="7" y="${y+4}" fill="#7c98ad" font-size="10">${f(r.height)}m</text><text x="${x+8}" y="${y+4}" fill="#397aa5" font-size="11">${f(r.tws)} kn</text>`;}).join('')}<text x="42" y="169" fill="#7c98ad" font-size="10">0</text><text x="242" y="169" fill="#7c98ad" font-size="10">${f(s.windSpeed)} kn</text></svg><table class="wind-profile-table"><thead><tr><th>${lang('Quota','Height')}</th><th>${lang('Reale','True')}</th><th>${lang('Apparente','Apparent')}</th><th>${lang('Angolo app.','App. angle')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${f(r.height)} m</td><td>${f(r.tws)} kn</td><td>${f(r.aws)} kn</td><td>${f(Math.abs(r.awa))}°</td></tr>`).join('')}</tbody></table><p>${lang('Il valore impostato è in testa all’armo. Più in basso il vento diminuisce e in bolina l’apparente viene più da prua.','The set value is at the rig head. Wind decreases lower down; upwind, apparent wind comes further forward.')}</p><details id="windProfileRule"><summary>${lang('Regola e riferimento della polare','Rule and polar reference')}</summary><p>V(z) = V(H) × (z/H)<sup>${f(windExponent(s),2)}</sup> · z ≥ 1,5 m.<br>${lang('Vento equivalente a 10 m per leggere la polare ORC','Equivalent wind at 10 m for the ORC polar')}: ${f(polarWindSpeed(s),2)} kn. ${lang('Profilo medio; l’interazione tra vele modifica ulteriormente il flusso locale.','Mean profile; sail interaction further changes local flow.')}</p></details>`;
 root.querySelector('details').toggleAttribute('open',!!wasOpen);
 }
 button.addEventListener('click',()=>{getState().windProfileVisible=!getState().windProfileVisible;key=null;update();});return{update};}
